// New: per-unit pixel art for the tactical grid. Humans (player and NPCs) are drawn in the armor
// they actually wear - armor_atlas.png holds every faction armor sprite with its faction armband
// baked in - and mutants use mutant_atlas.png (cloaked variants swap in while IsCloaked). Both
// atlases and their cell order (GameData/SpriteAtlasIndex.cs) are generated by
// ArtSource/export_to_unity.py. Sliced at runtime with Sprite.Create, which doesn't need the
// texture to be readable, so the normal PixelSpriteImporter settings are enough.
// Returns null for anything without art; TacticalGridView then keeps its old fallback marker.
using System.Collections.Generic;
using GameData;
using UnityEngine;

namespace GameCore
{
    public static class UnitSprites
    {
        private const int Cell = 16;
        private static Dictionary<string, Sprite> _armor, _mutants, _walkA, _walkB, _back, _backWalkA, _backWalkB;
        // Batch 29: the project enters Play mode without a domain reload, so statics survive between
        // runs while the sprites/textures they point at are destroyed - clear the caches each run.
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        private static void ResetCaches() { _hd = null; _vat = null; _armor = _mutants = _walkA = _walkB = _back = _backWalkA = _backWalkB = null; _poses.Clear(); }

        // Melee 3 (Yan: "the body doesn't use any of the new animation frames during swings"): the swing poses of every suit
        // (ArtSource/make_poses.py atlas): armor_pose_<key> / armor_back_pose_<key>, laid out like the armor atlases, plus a unique
        // suit's armor_unique_<name>_poses strip (front row, back row). Keys: crouch (sneaking), crouch_h, lunge_h_r/l, lunge_r/l, stagger_h_r/l, stagger_r/l.
        public static readonly string[] PoseKeys = { "crouch", "crouch_h", "kneel", "kneel_h", "lean_h_l", "lean_h_r", "lean_l", "lean_r", "lunge_h_l", "lunge_h_r",
            "lunge_l", "lunge_r", "lying", "sit_h_l", "sit_h_r", "sit_l", "sit_r", "stagger_h_l", "stagger_h_r", "stagger_l", "stagger_r" };   // sorted, as make_poses.py writes them
        private static readonly Dictionary<string, Dictionary<string, Sprite>> _poses = new Dictionary<string, Dictionary<string, Sprite>>();
        public static Sprite Pose(ICombatant unit, string key, bool away)
        {
            if (key == null) return null;
            Load();
            var armor = unit is Player p ? p.EquippedArmor : unit is HumanEnemy h ? h.EquippedArmor : null;
            string set = (away ? "armor_back_pose_" : "armor_pose_") + key;
            if (!_poses.TryGetValue(set, out var d)) _poses[set] = d = Slice("Sprites/" + set, SpriteAtlasIndex.Armor);
            return armor != null && d.TryGetValue(armor.Name, out var s) ? s : null;
        }

        /// <summary>Batch 128 (Yan: "add the back as well so the player can know which way the npc's are looking"): a unit
        /// whose aim (or gaze) from `from` to `to` goes up the screen shows its back - more than ~17 degrees above level.</summary>
        public static bool Away(Vector3 from, Vector3 to)
        {
            float dx = to.x - from.x, dy = to.y - from.y;
            return dy > 0.3f * Mathf.Sqrt(dx * dx + dy * dy) && dy > 0.001f;
        }

        /// <summary>Batch 128: the back view of a human (armor_back_atlas.png, ArtSource/make_back_atlas.py); null for mutants.</summary>
        public static Sprite Back(ICombatant unit)
        {
            Load();
            var armor = unit is Player p ? p.EquippedArmor : unit is HumanEnemy h ? h.EquippedArmor : null;
            return armor != null && _back.TryGetValue(armor.Name, out var s) ? s : null;
        }


        static Sprite[] _vat;
        /// <summary>Boss 2: the vat sheet (ArtSource/bosses/make_brain_vat.py): 8 columns x 11 rows of 128x160 at double resolution,
        /// row-major from the top (BrainBoss.ArtRow/ArtCol), the base on the tile.</summary>
        static Sprite[] VatFrames()
        {
            if (_vat != null) return _vat.Length > 0 ? _vat : null;
            var tex = Resources.Load<Texture2D>("Sprites/Mutants/boss_brain_vat");
            if (tex == null) { _vat = new Sprite[0]; return null; }
            tex.filterMode = FilterMode.Point;
            int cols = tex.width / 128, rows = tex.height / 160; _vat = new Sprite[cols * rows];
            for (int r = 0; r < rows; r++)
                for (int c = 0; c < cols; c++)
                    _vat[r * cols + c] = Sprite.Create(tex, new Rect(c * 128, tex.height - (r + 1) * 160, 128, 160), new Vector2(0.5f, 10f / 160f), 2 * Cell, 0, SpriteMeshType.FullRect);
            return _vat;
        }

        public static Sprite For(ICombatant unit)
        {
            Load();
            switch (unit)
            {
                case Player p: return ForArmor(p.EquippedArmor);
                case HumanEnemy h: return ForArmor(h.EquippedArmor);
                case Mutant m:
                    string name = m.Db?.Name ?? m.Name;
                    var hd = HD(name);
                    if (hd != null) return hd;                                       // the approved double-resolution art (Batch 130c)
                    if (m.IsCloaked && _mutants.TryGetValue(name + " (cloaked)", out var cloaked)) return cloaked;
                    return _mutants.TryGetValue(name, out var s) ? s : null;
                default: return null;
            }
        }

        // Batch 130c's mutants at double resolution (ArtSource/make_mutants_hd.py -> Sprites/Mutants/mutant_hd_<key>.png): 32 px a
        // tile like the in-hand guns, so a 48x32 hound covers the ground a 24x16 one would; the feet sit on the tile's ground
        // line (16 px under the middle of a tile, where a 16 px human's feet are). They face right; TacticalGridView mirrors them.
        // Mutants without one keep their old atlas cell (Rot Swarm, Alpha Prowler, Mind Weaver, Void Weaver).
        private static Dictionary<string, Sprite> _hd;
        public static Sprite HD(string name)
        {
            if (name == BrainBoss.Name) { var v = VatFrames(); return v == null ? null : v[BrainBoss.ArtRow * 8 + BrainBoss.ArtCol]; }   // Boss 2: the vat, by phase and moment
            if (_hd == null)
            {
                _hd = new Dictionary<string, Sprite>();
                foreach (var n in new[] { "Pallid Prowler", "Blind Maw", "Veil Prowler", "Dread Prowler", "Blight Brute" })
                {
                    var tex = Resources.Load<Texture2D>("Sprites/Mutants/mutant_hd_" + n.ToLowerInvariant().Replace(' ', '_'));
                    if (tex != null) _hd[n] = Sprite.Create(tex, new Rect(0, 0, tex.width, tex.height), new Vector2(0.5f, 16f / tex.height), 2 * Cell, 0, SpriteMeshType.FullRect);
                }
            }
            return name != null && _hd.TryGetValue(name, out var s) ? s : null;
        }

        // 2026-11-11: walk strips (ArtSource/export_mutant_walk.py -> Sprites/Mutants/anim/<key>_walk.bytes): 8 frames in a row, decoded here like the world atlas so no import setting can blur them.
        // Same density and pivot as the HD stand-still sprite (32 px a tile, the feet on the bottom row, the pivot 16 px above it, the head to the right). Pallid and Veil Prowler have one so far.
        public const int WalkFrames = 8;
        private static Dictionary<string, Sprite[]> _hdWalk;
        public static Sprite[] HDWalk(string name)
        {
            if (name == null) return null;
            if (_hdWalk == null) _hdWalk = new Dictionary<string, Sprite[]>();
            if (_hdWalk.TryGetValue(name, out var cached)) return cached;
            Sprite[] frames = null;
            var asset = Resources.Load<TextAsset>("Sprites/Mutants/anim/" + name.ToLowerInvariant().Replace(' ', '_') + "_walk");
            if (asset != null)
            {
                var tex = new Texture2D(2, 2, TextureFormat.RGBA32, false);
                if (tex.LoadImage(asset.bytes) && tex.width % WalkFrames == 0)
                {
                    tex.filterMode = FilterMode.Point; tex.wrapMode = TextureWrapMode.Clamp;
                    int w = tex.width / WalkFrames; frames = new Sprite[WalkFrames];
                    for (int i = 0; i < WalkFrames; i++) frames[i] = Sprite.Create(tex, new Rect(i * w, 0, w, tex.height), new Vector2(0.5f, 16f / tex.height), 2 * Cell, 0, SpriteMeshType.FullRect);
                }
            }
            _hdWalk[name] = frames;
            return frames;
        }

        public static Sprite ForArmor(ArmorDef armor)
        {
            Load();
            return armor != null && _armor.TryGetValue(armor.Name, out var s) ? s : null;
        }

        /// <summary>Batch 24: walking frame (0 = left foot up, 1 = right) for humans, null for mutants
        /// or when the walk atlases (ArtSource/make_walk_atlas.py) aren't in the project.</summary>
        public static Sprite Walk(ICombatant unit, int frame, bool away = false)
        {
            Load();
            var armor = unit is Player p ? p.EquippedArmor : unit is HumanEnemy h ? h.EquippedArmor : null;
            var set = away ? (frame == 0 ? _backWalkA : _backWalkB) : frame == 0 ? _walkA : _walkB;
            return armor != null && set.TryGetValue(armor.Name, out var s) ? s : null;
        }

        private static void Load()
        {
            if (_armor != null) return;
            _walkA = Slice("Sprites/armor_walk_a", SpriteAtlasIndex.Armor);
            _walkB = Slice("Sprites/armor_walk_b", SpriteAtlasIndex.Armor);
            _armor = Slice("Sprites/armor_atlas", SpriteAtlasIndex.Armor);
            _back = Slice("Sprites/armor_back_atlas", SpriteAtlasIndex.Armor);
            _backWalkA = Slice("Sprites/armor_back_walk_a", SpriteAtlasIndex.Armor);
            _backWalkB = Slice("Sprites/armor_back_walk_b", SpriteAtlasIndex.Armor);
            _mutants = Slice("Sprites/mutant_atlas", SpriteAtlasIndex.Mutants);
            foreach (var name in UniqueSuits) Unique(name);
        }

        /// <summary>Boss 1: one-of-a-kind suits outside the faction atlases (ArtSource/make_unique_armor.py): a 96x16 strip -
        /// front, walk a, walk b, back, back walk a, back walk b - added under the suit's name like an atlas cell.</summary>
        public static readonly string[] UniqueSuits = { "Black Visor Suit" };
        public static readonly Dictionary<string, (string cuff, string glove)> UniqueGloves = new Dictionary<string, (string, string)>
            { ["Black Visor Suit"] = ("#1f2226", "#2a2c30") };

        static void Unique(string name)
        {
            var tex = LoadX2("Sprites/armor_unique_" + System.Text.RegularExpressions.Regex.Replace(name.ToLowerInvariant(), "[^a-z0-9]+", "_").Trim('_'));
            if (tex == null) return;
            var sets = new[] { _armor, _walkA, _walkB, _back, _backWalkA, _backWalkB };
            int uc = tex.height;                                                   // 2026-11-09: the cell is read from the texture (16 px drawn, 32 px doubled)
            for (int i = 0; i < 6; i++) sets[i][name] = Sprite.Create(tex, new Rect(i * uc, 0, uc, uc), new Vector2(0.5f, 0.5f), uc, 0, SpriteMeshType.FullRect);
            var poses = LoadX2("Sprites/armor_unique_" + System.Text.RegularExpressions.Regex.Replace(name.ToLowerInvariant(), "[^a-z0-9]+", "_").Trim('_') + "_poses");
            if (poses == null) return;
            int pc = poses.height / 2;
            for (int r = 0; r < 2; r++)                                            // texture row 0 is the bottom: the back row
                for (int i = 0; i < PoseKeys.Length; i++)
                {
                    string set = (r == 0 ? "armor_back_pose_" : "armor_pose_") + PoseKeys[i];
                    if (!_poses.TryGetValue(set, out var d)) _poses[set] = d = Slice("Sprites/" + set, SpriteAtlasIndex.Armor);
                    d[name] = Sprite.Create(poses, new Rect(i * pc, r * pc, pc, pc), new Vector2(0.5f, 0.5f), pc, 0, SpriteMeshType.FullRect);
                }
        }

        /// <summary>2026-11-09: the doubled copy (`<name>_x2`, ArtSource/double_armor.py: 32 px cells) when it exists, else the 16 px file as drawn.</summary>
        private static Texture2D LoadX2(string path)
        {
            var big = Resources.Load<Texture2D>(path + "_x2");
            return big != null ? big : Resources.Load<Texture2D>(path);
        }

        private static Dictionary<string, Sprite> Slice(string path, string[] order)
        {
            var sprites = new Dictionary<string, Sprite>();
            var tex = LoadX2(path);
            if (tex == null) return sprites;
            int cell = tex.width / SpriteAtlasIndex.Columns;                       // 2026-11-09: 16 px cells as drawn, 32 px when doubled (ArtSource/double_armor.py): same size on screen
            for (int i = 0; i < order.Length; i++)
            {
                int col = i % SpriteAtlasIndex.Columns, row = i / SpriteAtlasIndex.Columns;
                var rect = new Rect(col * cell, tex.height - (row + 1) * cell, cell, cell); // atlas row 0 is the top
                sprites[order[i]] = Sprite.Create(tex, rect, new Vector2(0.5f, 0.5f), cell, 0, SpriteMeshType.FullRect);
            }
            return sprites;
        }
    }
}
